CREATE TABLE "notificacao" ("id" UUID NOT NULL, "usuario_id" UUID NOT NULL, "tipo" VARCHAR(32) NOT NULL, "titulo" VARCHAR(160) NOT NULL, "mensagem" TEXT NOT NULL, "midia_id" VARCHAR(255), "dados" JSONB, "lida_at" TIMESTAMP(3), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "notificacao_pkey" PRIMARY KEY ("id"));CREATE INDEX "notificacao_usuario_id_lida_at_idx" ON "notificacao"("usuario_id", "lida_at");CREATE INDEX "notificacao_midia_id_idx" ON "notificacao"("midia_id");ALTER TABLE "notificacao" ADD CONSTRAINT "notificacao_usuario_id_fkey" FOREIGN KEY ("usuario_id") REFERENCES "usuario"("id") ON DELETE CASCADE ON UPDATE CASCADE;
